    #include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;

void dfs(int node, int currDist, vector<vector<pair<int, int>>> &adj, vector<int> &dist)
{
    dist[node] = max(dist[node], currDist);

    for (auto &it : adj[node])
    {
        int v = it.first;
        int wt = it.second;

        dfs(v, currDist + wt, adj, dist);
    }
}

vector<int> maxDistance(int V, int src, vector<vector<int>> &edges)
{
    // Build adjacency list
    vector<vector<pair<int, int>>> adj(V);

    for (auto &edge : edges)
    {
        int u = edge[0];
        int v = edge[1];
        int wt = edge[2];

        adj[u].push_back({v, wt});
    }

    // Initialize distances
    vector<int> dist(V, INT_MIN);

    // Start DFS from source
    dfs(src, 0, adj, dist);

    return dist;
}

int main()
{
    int V = 5, src = 1;

    vector<vector<int>> edges = {{0, 1, 1}, {0, 2, 2}, {1, 4, 4}, {3, 2, -1}, {4, 2, 3}, {4, 3, 6}};

    vector<int> ans = maxDistance(V, src, edges);

    cout << "[";

    for (int i = 0; i < ans.size(); i++)
    {
        if (ans[i] == INT_MIN)
            cout << "INF";
        else
            cout << ans[i];

        if (i!= ans.size() - 1)
            cout << ",";
    }

    cout << "]";

    return 0;
}


