        for (int i = 0; i < V; i++)
            if (indegree[i] == 0)
                q.Enqueue(i);

        List<int> topoOrder = new List<int>();

        while (q.Count > 0) {
            int node = q.Dequeue();
            topoOrder.Add(node);

            foreach(var it in g[node])
            {
                int v = it.Item1;
                if (--indegree[v] == 0)
                    q.Enqueue(v);
